actions.script:
import org.slf4j.LoggerFactory
def logger = LoggerFactory.getLogger("ExtensibilityServices")

logger.info("Saving Custom Field Value: [DefId: ${fieldDefId}, EntityId: ${entityId}, Value: ${fieldValue}]")

// MOCK EXTENSIBILITY SAVE LOGIC
// In production, this checks if a value already exists for this entityId and fieldDefId.
// If it exists, update it. If not, create a new zenith.erp.studio.CustomFieldValue record.

logger.info("Custom Field Value Saved Successfully.")

import org.slf4j.LoggerFactory
def logger = LoggerFactory.getLogger("ExtensibilityServices")

logger.info("Fetching Custom Fields for EntityId: ${entityId}")

// MOCK EXTENSIBILITY GET LOGIC
customFields = [
    [fieldName: "T-Shirt Size", fieldValue: "Large"],
    [fieldName: "Dietary Restrictions", fieldValue: "Vegetarian"]
]

logger.info("Fetched ${customFields.size()} custom fields.")
